from pathlib import Path
import ast
import hashlib
import json
import zipfile
from email.parser import BytesParser
from urllib.parse import urlsplit

ROOT=Path('/workspace/engineering/oauth-released-source-discovery')
OUT=Path('/workspace/engineering/oauth-released-source-independent-review')

def binding(p):
    b=p.read_bytes()
    return {'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}

metadata=ROOT/'runtime-102-public-metadata.json'
m=json.loads(metadata.read_text())
assert m['info']['name']=='actions-runtime' and m['info']['version']=='1.0.2'
candidates=[d for d in m['urls'] if '-cp312-cp312-' in d['filename'] and 'manylinux' in d['filename']]
assert len(candidates)==1
candidate=candidates[0]
assert json.loads((ROOT/'linux-cp312-candidates.json').read_text())==[{'filename':candidate['filename'],'size':candidate['size'],'sha256':candidate['digests']['sha256'],'url':candidate['url']}]
u=urlsplit(candidate['url'])
assert u.scheme=='https' and u.hostname=='files.pythonhosted.org'
assert not u.username and not u.password and not u.query and not u.fragment
assert candidate['packagetype']=='bdist_wheel' and candidate['python_version']=='cp312' and not candidate['yanked']
wheel=ROOT/candidate['filename']
measured=binding(wheel)
assert measured['bytes']==candidate['size']==14095731
assert measured['sha256']==candidate['digests']['sha256']=='9aef9ec55c17d90ec11a32d8d4da694def92502ba46a73621c35267f230873d3'
member='actions/server/_oauth2_config.py'
with zipfile.ZipFile(wheel) as z:
    assert z.namelist().count(member)==1
    info=z.getinfo(member);assert info.file_size==287
    raw=z.read(member)
    meta_paths=[p for p in z.namelist() if p.endswith('.dist-info/METADATA')]
    assert len(meta_paths)==1
    package=BytesParser().parsebytes(z.read(meta_paths[0]))
    assert package['Name']=='actions-runtime' and package['Version']=='1.0.2'
assert hashlib.sha256(raw).hexdigest()=='f79d95697f1b20691cfff74faa422dc5fa9a13e7fd5d16e98bac3572c6dd7dbe'
module=ast.parse(raw.decode('utf-8',errors='strict'))
assert len(module.body)==1 and isinstance(module.body[0],ast.Assign)
assignment=module.body[0]
assert len(assignment.targets)==1 and isinstance(assignment.targets[0],ast.Name) and assignment.targets[0].id=='FILE_CONTENTS'
contents=ast.literal_eval(assignment.value)
assert isinstance(contents,dict) and set(contents)=={'actions_config','default_user_config'}
assert all(type(v) is str and not v for v in contents.values())
next_wheel=Path('/workspace/actions-cloud/receipts/runtime-103-preflight/linux-cp312-input/actions_runtime-1.0.3-cp312-cp312-manylinux_2_5_x86_64.manylinux1_x86_64.manylinux_2_17_x86_64.manylinux2014_x86_64.whl')
assert binding(next_wheel)['sha256']=='0f366268f7590e2c0002b8f7e67325810d0d5374775c657b19195c80da48eaaa'
with zipfile.ZipFile(next_wheel) as z:
    assert z.namelist().count(member)==1
    assert z.read(member)==raw
discovery=ROOT/'generated-member-discovery.json'
d=json.loads(discovery.read_text())
assert d['wheel']['sha256']==measured['sha256'] and d['wheel']['bytes']==measured['bytes']
assert d['member']['sha256']==hashlib.sha256(raw).hexdigest() and d['member']['bytes']==len(raw)
assert d['schema']=='FILE_CONTENTS mapping'
proposal=OUT/'canonical-published-content-recovery-proposal.md'
proposal.write_text('''An existing published wheel can supply historical generated bytes for inspection; publication alone does not identify the owner-approved configuration source pair, revision or provider policy. Bind any proposed recovery input to the original public index metadata and whole-wheel digest, then inspect the actual generated member as data rather than executing it. Check its actual schema instead of assuming separate top-level assignments.

The selected published Runtime 1.0.2 Linux cp312 wheel is 14,095,731 bytes with SHA256 9aef9ec55c17d90ec11a32d8d4da694def92502ba46a73621c35267f230873d3, matching its retained public PyPI metadata. Its `actions/server/_oauth2_config.py` member is287 bytes/SHA256 f79d95697f1b20691cfff74faa422dc5fa9a13e7fd5d16e98bac3572c6dd7dbe and has one `FILE_CONTENTS` mapping assignment. Safe AST literal inspection finds the two expected strings empty. These member bytes are identical to the measured retained Runtime1.0.3 Linux cp312 wheel0f366268. This published predecessor therefore supplies no valid OAuth pair and cannot be used as a configuration fallback, source authority or release admission.

Keep this scoped content discovery separate from whole-release/platform qualification and from the existing narrow installed-wheel consumer result. The current checked guard rejects blank input, but these historical empty bytes neither prove how the predecessor was built nor establish an approved replacement source or disabled-provider policy. Preserve original receipts. The owner’s authoritative source pair/revision and supported provider requirements remain open. No download, installation, import/execution, source mutation, publication or infrastructure action was performed by the independent reviewer.

Canonical destination proposed: `docs/skills/repository-operations.md`, beside the OAuth source-authority and generated-content qualification guidance. Evidence: retained public metadata plus exact whole-wheel/member hashes and safe AST shape in the independent receipt. Stale ambiguity removed: a published version implies complete generated configuration or approved fallback authority; assuming a different assignment schema. Remaining uncertainty: approved source ownership/revision/provider policy and unmeasured other platform or release artifacts. Upstream disposition: none; no established upstream defect.
''')
result={
 'verdict':'GO_SCOPED_HISTORICAL_PUBLIC_WHEEL_CONTENT_DISCOVERY; HOLD_OAUTH_FALLBACK_SOURCE_AUTHORITY_AND_RUNTIME_PUBLICATION',
 'scope':'read-only original local metadata/wholewheel/member bytes and safe AST; no redownload/install/import/execute/source mutation or release action',
 'public_metadata':binding(metadata),'selected_candidate_record':{'filename':candidate['filename'],'size':candidate['size'],'sha256':candidate['digests']['sha256'],'packagetype':candidate['packagetype'],'python_version':candidate['python_version'],'yanked':candidate['yanked'],'url_class':'HTTPS files.pythonhosted.org public distribution; no credentials/query/fragment'},
 'original_whole_wheel':measured,'internal_distribution_metadata':{'name':package['Name'],'version':package['Version']},
 'generated_member':{'path':member,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'single_unique_zip_member':True,'AST_schema':'one Assign to FILE_CONTENTS mapping, no executable member evaluation','payloads':{k:{'type':'str','bytes':len(v.encode()),'blank':True,'sha256':hashlib.sha256(v.encode()).hexdigest()} for k,v in contents.items()}},
 'existing103_comparison':{'selected_whole_wheel':binding(next_wheel),'generated_member_byte_for_byte_equal':True,'historical103_producer':'12340bb17/tree80e5 retained38105853105 artifact11690296318; not relabeled as published'},
 'original_discovery_receipt':binding(discovery),'original_candidate_selection':binding(ROOT/'linux-cp312-candidates.json'),
 'limits':['Retained public metadata digest binds observed wheel bytes, not source authority, source revision, clean build or approved providers.','Selected Linuxcp3121.0.2 member only; no claim for all predecessor platforms/native binaries or full published release.','Both expected config strings empty: no valid nonblank structurally admitted OAuth source pair can be recovered here.','Identical historical empty member bytes do not establish why acquisition failed or how1.0.2 was produced.','No fallback, guessed repository/provider/disabled mode, successful skip, private metadata substitution or publication waiver.','Existing narrow Runtime1.0.3 installed-wheel/floor GO remains unchanged and separate from generated-content HOLD.'],
 'canonical_documentation':{'canonical_file':'docs/skills/repository-operations.md','exact_proposed_delta':binding(proposal),'disposition':'PROPOSED read-only scoped recovery lesson; no repo mutation','evidence':'retained PyPI metadata, measured9aef wholewheel, unique287-byte f79d generated member/safe AST and byte-equal existing0f366wheel','stale_ambiguity':'published content is approved source/fallback; published version implies complete generated configuration; incorrect assumed assignment schema','remaining_uncertainty':'owner-approved source pair/revision/provider requirements and other platform/release qualification','upstream':'none'},
}
p=OUT/'independent-published-member-content-review.json';p.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(binding(p)))
